const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".fc{box-sizing:border-box;width:100%;height:100%;min-height:0;display:flex;flex-direction:column;gap:6px;padding:10px;color:var(--ink);font:13px/1.4 \"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",system-ui,sans-serif}\n.fc *{box-sizing:border-box;min-width:0}\n.fc button,.fc textarea,.fc input{font:inherit;color:inherit}\n.fc button{touch-action:manipulation;-webkit-tap-highlight-color:transparent;cursor:pointer}\n.fc button:active{transform:scale(.98)}\n.fc button:focus-visible,.fc textarea:focus-visible,.fc input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.hd{display:flex;align-items:center;gap:6px;flex:none;min-height:30px}\n.tabs{display:flex;flex:1;gap:2px;padding:2px;border-radius:11px;background:var(--soft)}\n.tab{flex:1;display:flex;align-items:center;justify-content:center;gap:5px;height:26px;padding:0 6px;border:0;border-radius:9px;background:transparent;color:var(--muted);font-weight:600;white-space:nowrap}\n.tab.on{background:var(--panel-paper);color:var(--ink);box-shadow:0 0 0 1px var(--line)}\n.bd{min-width:17px;height:17px;padding:0 5px;border-radius:9px;background:var(--line);color:var(--ink);font-size:11px;font-weight:600;line-height:17px;text-align:center}\n.tab.hot .bd{background:var(--accent);color:var(--on-accent)}\n.add{flex:none;display:flex;align-items:center;justify-content:center;gap:4px;height:30px;min-width:30px;padding:0 10px;border:0;border-radius:11px;background:var(--accent);color:var(--on-accent);font-weight:700}\n.pl{font-size:18px;line-height:1}\n.back{flex:none;height:30px;padding:0 10px;border:1px solid var(--line);border-radius:11px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600}\n.ttl{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;font-weight:700}\n.ttl.ok{color:var(--accent)}\n.ttl.err{text-decoration:underline;text-decoration-color:var(--accent);text-underline-offset:3px}\n\n.pane{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.stat{flex:none;display:none;color:var(--muted);font-size:12px}\n.fail{flex:none;padding:4px 8px;border:1px solid var(--accent);border-radius:8px;background:var(--soft);font-size:12px;font-weight:600}\n\n.rv{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.face{flex:1;min-height:0;display:flex;flex-direction:column;padding:6px 10px 8px;border:1px solid var(--line);border-radius:14px;background:var(--panel-paper)}\n.ft{flex:none;display:flex;align-items:center;gap:6px;min-height:24px;color:var(--muted);font-size:11px}\n.fl{color:var(--accent);font-weight:700;letter-spacing:.05em}\n.cnt{flex:1;overflow:hidden;text-align:right;text-overflow:ellipsis;white-space:nowrap}\n.ico{flex:none;width:26px;height:26px;padding:0;border:0;border-radius:7px;background:transparent;color:var(--muted);font-size:14px}\n.fb{flex:1;min-height:0;display:flex;flex-direction:column;overflow-y:auto;overscroll-behavior:contain}\n.fb>*{flex:none}\n.tx{margin:auto 0;font-size:15px;font-weight:600;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}\n.qm{margin-bottom:6px;padding-bottom:6px;border-bottom:1px dashed var(--line);color:var(--muted);font-size:12px;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow-wrap:anywhere;white-space:pre-wrap}\n.face.ans{animation:fcflip .26s ease-out}\n@keyframes fcflip{from{opacity:.25;transform:rotateX(-60deg)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.face.ans{animation:none}.fc button:active{transform:none}}\n\n.acts{flex:none;display:flex;gap:6px}\n.flip{flex:1;height:40px;border:0;border-radius:12px;background:var(--accent);color:var(--on-accent);font-size:14px;font-weight:700}\n.rate{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;height:42px;padding:2px;border:1px solid var(--line);border-radius:12px;background:var(--button-paper,var(--panel-paper));color:var(--ink)}\n.rl{display:flex;align-items:center;gap:3px;font-size:12px;font-weight:700;white-space:nowrap}\n.rd{color:var(--muted);font-size:11px;white-space:nowrap}\n.ic{font-weight:700}\n.rate.good{border-color:var(--accent);background:var(--accent);color:var(--on-accent)}\n.rate.good .rd{color:var(--on-accent);opacity:.88}\n.rate.hard{border-color:var(--accent);background:var(--soft)}\n.rate.hard .rd{color:var(--ink)}\n\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;overflow-y:auto}\n.inner{margin:auto;display:flex;flex-direction:column;align-items:center;gap:4px;padding:2px 4px;text-align:center}\n.mark{display:flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:50%;background:var(--soft);color:var(--accent);font-size:20px;font-weight:700}\n.et{font-size:15px;font-weight:700}\n.es{color:var(--muted);font-size:12px}\n.wide{margin-top:6px;padding:0 18px}\n.rule{align-self:stretch;margin-top:8px;padding-top:6px;border-top:1px dashed var(--line);color:var(--muted);font-size:11px;line-height:1.5;text-align:left}\n.rule>div:first-child{color:var(--ink);font-weight:700}\n\n.srch{flex:none;height:30px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink)}\n.rows{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px;overflow-y:auto;overscroll-behavior:contain;align-content:start}\n.row{flex:none;display:flex;flex-direction:column;gap:3px;width:100%;padding:7px 10px;border:1px solid var(--line);border-radius:12px;background:var(--panel-paper);color:var(--ink);text-align:left}\n.rq{font-weight:600;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow-wrap:anywhere}\n.ra{display:none;color:var(--muted);font-size:12px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\n.rm{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:11px}\n.chip{padding:1px 8px;border-radius:9px;background:var(--soft);color:var(--ink);white-space:nowrap}\n.chip.hot{background:var(--accent);color:var(--on-accent)}\n.dots{display:flex;gap:3px;margin-left:auto}\n.dots i{width:6px;height:6px;border-radius:50%;background:var(--line)}\n.dots i.on{background:var(--accent)}\n.none{padding:12px;color:var(--muted);text-align:center}\n\n.fm{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.flds{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.fld{flex:1;min-height:0;display:flex;flex-direction:column;gap:2px}\n.lab{flex:none;color:var(--muted);font-size:11px;font-weight:700}\n.ta{flex:1;min-height:0;width:100%;resize:none;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font-size:14px;line-height:1.4}\n.info{flex:none;display:none;color:var(--muted);font-size:12px}\n.facts{flex:none;display:flex;gap:6px}\n.pri{flex:1;height:34px;padding:0 14px;border:0;border-radius:11px;background:var(--accent);color:var(--on-accent);font-weight:700}\n.sec{flex:none;height:34px;padding:0 14px;border:1px solid var(--line);border-radius:11px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600}\n.wide{flex:none;height:34px}\n\n/* 3x3\uff1a\u6700\u7d27\u51d1 */\n.card[data-size=\"3x3\"] .fc{padding:8px;gap:5px}\n.card[data-size=\"3x3\"] .hd{min-height:28px}\n.card[data-size=\"3x3\"] .tabs{padding:1px}\n.card[data-size=\"3x3\"] .tab{height:26px;padding:0 4px;gap:3px}\n.card[data-size=\"3x3\"] .add{width:28px;height:28px;padding:0}\n.card[data-size=\"3x3\"] .al{display:none}\n.card[data-size=\"3x3\"] .qm{display:none}\n.card[data-size=\"3x3\"] .cnt{display:none}\n.card[data-size=\"3x3\"] .ft{min-height:22px}\n.card[data-size=\"3x3\"] .ico{margin-left:auto}\n.card[data-size=\"3x3\"] .face{padding:4px 8px 6px}\n.card[data-size=\"3x3\"] .tx{font-size:14px}\n.card[data-size=\"3x3\"] .rate{height:40px}\n.card[data-size=\"3x3\"] .rl{font-size:11.5px}\n.card[data-size=\"3x3\"] .ic{display:none}\n.card[data-size=\"3x3\"] .flip{height:38px}\n.card[data-size=\"3x3\"] .back{padding:0 8px;height:28px}\n.card[data-size=\"3x3\"] .ttl{font-size:13px}\n.card[data-size=\"3x3\"] .mark{width:28px;height:28px;font-size:16px}\n.card[data-size=\"3x3\"] .et{font-size:14px}\n.card[data-size=\"3x3\"] .pri,.card[data-size=\"3x3\"] .sec{height:32px;padding:0 10px}\n\n/* 6x3\uff1a\u5de6\u9898\u53f3\u64cd\u4f5c */\n.card[data-size=\"6x3\"] .rv{flex-direction:row}\n.card[data-size=\"6x3\"] .acts{flex-direction:column;width:124px}\n.card[data-size=\"6x3\"] .flip{height:auto;flex:1}\n.card[data-size=\"6x3\"] .rate{flex:1 1 0;height:auto;min-height:0;flex-direction:row;justify-content:space-between;padding:0 8px}\n.card[data-size=\"6x3\"] .tx{font-size:16px}\n.card[data-size=\"6x3\"] .qm{-webkit-line-clamp:1}\n.card[data-size=\"6x3\"] .rows{display:grid;grid-template-columns:1fr 1fr;align-content:start}\n.card[data-size=\"6x3\"] .ra{display:block}\n.card[data-size=\"6x3\"] .flds{flex-direction:row}\n.card[data-size=\"6x3\"] .rule,.card[data-size=\"6x3\"] .none{grid-column:1/-1}\n\n/* 3x6\uff1a\u7ad6\u5411\u5806\u53e0 */\n.card[data-size=\"3x6\"] .stat{display:block}\n.card[data-size=\"3x6\"] .acts{flex-direction:column}\n.card[data-size=\"3x6\"] .flip{height:44px}\n.card[data-size=\"3x6\"] .rate{flex:none;height:42px;flex-direction:row;justify-content:space-between;padding:0 12px}\n.card[data-size=\"3x6\"] .tx{font-size:18px}\n.card[data-size=\"3x6\"] .info{display:block}\n\n/* 6x6\uff1a\u5bbd\u677e */\n.card[data-size=\"6x6\"] .fc{padding:16px;gap:10px}\n.card[data-size=\"6x6\"] .hd{min-height:34px}\n.card[data-size=\"6x6\"] .tab{height:30px;font-size:14px}\n.card[data-size=\"6x6\"] .add{height:34px;padding:0 14px;font-size:14px}\n.card[data-size=\"6x6\"] .stat{display:block;font-size:13px}\n.card[data-size=\"6x6\"] .rv{gap:10px}\n.card[data-size=\"6x6\"] .face{padding:10px 16px 14px}\n.card[data-size=\"6x6\"] .tx{font-size:24px}\n.card[data-size=\"6x6\"] .qm{font-size:14px;-webkit-line-clamp:3}\n.card[data-size=\"6x6\"] .flip{height:50px;font-size:16px}\n.card[data-size=\"6x6\"] .rate{height:60px}\n.card[data-size=\"6x6\"] .rl{font-size:15px}\n.card[data-size=\"6x6\"] .rd{font-size:12px}\n.card[data-size=\"6x6\"] .rows{display:grid;grid-template-columns:1fr 1fr;align-content:start;gap:8px}\n.card[data-size=\"6x6\"] .ra{display:block}\n.card[data-size=\"6x6\"] .rule,.card[data-size=\"6x6\"] .none{grid-column:1/-1}\n.card[data-size=\"6x6\"] .info{display:block}\n.card[data-size=\"6x6\"] .pri,.card[data-size=\"6x6\"] .sec{height:40px}\n";
/* 知识点记忆卡：间隔复习（5 级简化 Leitner） */
const FC_INTERVALS=[1,3,7,14,30,60,120];
const FC_MAXLV=6;

function fcParse(s){
  const p=String(s||'').split('-').map(Number);
  return new Date(p[0]||1970,(p[1]||1)-1,p[2]||1);
}
function fcFmt(d){
  const m=d.getMonth()+1,x=d.getDate();
  return d.getFullYear()+'-'+(m<10?'0':'')+m+'-'+(x<10?'0':'')+x;
}
function fcAddDays(s,n){
  const d=fcParse(s);
  d.setDate(d.getDate()+n);
  return fcFmt(d);
}
function fcDiff(a,b){
  const A=fcParse(a),B=fcParse(b);
  return Math.round((Date.UTC(B.getFullYear(),B.getMonth(),B.getDate())-Date.UTC(A.getFullYear(),A.getMonth(),A.getDate()))/86400000);
}
/* g: good=记住了 hard=勉强记得 bad=忘了 */
function fcPlan(c,g){
  const lv=c.level||0;
  if(g==='good'){
    const n=Math.min(lv+1,FC_MAXLV);
    return {level:n,days:FC_INTERVALS[n]};
  }
  if(g==='hard'){
    return {level:lv,days:lv===0?2:Math.max(2,Math.round(FC_INTERVALS[lv]/2))};
  }
  return {level:0,days:1};
}
function fcDayText(n){
  if(n<=1)return '明天';
  if(n>=60)return Math.round(n/30)+'个月后';
  return n+'天后';
}
function fcDueText(due,today){
  const d=fcDiff(today,due);
  if(d<0)return '逾期'+(-d)+'天';
  if(d===0)return '今天';
  if(d===1)return '明天';
  if(d<100)return d+'天后';
  return due;
}
function fcByDue(a,b){
  if(a.due<b.due)return -1;
  if(a.due>b.due)return 1;
  return (a.created||0)-(b.created||0);
}


function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const today=day();
  const raw=Array.isArray(state&&state.cards)?state.cards:[];
  const cards=raw.filter(c=>c&&c.id).map(c=>Object.assign({},c,{q:String(c.q||''),a:String(c.a||''),due:c.due||today}));
  const queue=cards.filter(c=>c.due<=today).sort(fcByDue);
  const doneToday=cards.filter(c=>c.last===today).length;
  const compact=ctx.size==='3x3';
  if(!ui.tab)ui.tab='review';

  function clear(n){while(n.firstChild)n.removeChild(n.firstChild);}
  function btn(cls,label,fn,extra){
    return el('button',Object.assign({type:'button','class':cls,onclick:fn},extra||{}),label);
  }
  function nextUi(o){
    return Object.assign({tab:'review',curId:ui.curId||null,revealed:false,busy:false,draft:null,confirmDel:false,back:null,focus:null,fail:'',search:ui.search||''},o||{});
  }
  function save(fn,next){
    if(ui.busy)return;
    ui.busy=true;
    const fail=()=>{
      ui.busy=false;
      if(ui.tab==='form'&&ui.draft)ui.draft.err='保存失败，请重试';
      else ui.fail='保存失败，请重试';
      redraw();
    };
    let p;
    try{p=commit(fn,next);}catch(e){fail();return;}
    Promise.resolve(p).then(ok=>{if(ok===false)fail();},fail);
  }
  function rate(c,g){
    const id=c.id;
    save(s=>{
      const t=day();
      const list=(s.cards||[]).map(x=>{
        if(x.id!==id)return x;
        const p=fcPlan(x,g);
        return Object.assign({},x,{level:p.level,due:fcAddDays(t,p.days),last:t,reps:(x.reps||0)+1,lapses:(x.lapses||0)+(g==='bad'?1:0)});
      });
      return Object.assign({},s,{cards:list});
    },nextUi({revealed:false}));
  }
  function openForm(c,back){
    ui.tab='form';ui.back=back;ui.confirmDel=false;ui.busy=false;ui.fail='';ui.focus=null;
    ui.draft=c?{id:c.id,q:c.q,a:c.a,err:'',note:''}:{id:null,q:'',a:'',err:'',note:''};
    redraw();
  }

  function tabBtn(k,label,n,hot){
    return el('button',{type:'button','class':'tab'+(ui.tab===k?' on':'')+(hot?' hot':''),role:'tab','aria-selected':ui.tab===k?'true':'false',
      onclick:()=>{if(ui.tab!==k){ui.tab=k;ui.fail='';redraw();}}},
      el('span',{'class':'tl'},label),el('span',{'class':'bd'},String(n)));
  }
  function tabsHeader(){
    return el('div',{'class':'hd'},
      el('div',{'class':'tabs',role:'tablist'},tabBtn('review','复习',queue.length,queue.length>0),tabBtn('list','全部',cards.length,false)),
      el('button',{type:'button','class':'add',onclick:()=>openForm(null,ui.tab),'aria-label':'添加卡片',title:'添加卡片'},
        el('span',{'class':'pl'},'+'),el('span',{'class':'al'},'添加')));
  }
  function ruleEl(){
    return el('div',{'class':'rule'},
      el('div',{},'复习安排'),
      el('div',{},'记住了：升一级，下次间隔依次为 3、7、14、30、60、120 天'),
      el('div',{},'勉强记得：级别不变，间隔减半（至少 2 天）'),
      el('div',{},'忘了：回到起点，明天再来'));
  }
  function emptyView(mark,title,lines,withAdd){
    const kids=[el('div',{'class':'mark','aria-hidden':'true'},mark),el('div',{'class':'et'},title)];
    lines.forEach(t=>kids.push(el('div',{'class':'es'},t)));
    if(withAdd)kids.push(btn('pri wide','添加卡片',()=>openForm(null,ui.tab)));
    return el('div',{'class':'empty'},el('div',{'class':'inner'},...kids));
  }

  function reviewView(){
    const pane=[];
    if(ui.fail)pane.push(el('div',{'class':'fail',role:'alert'},'！'+ui.fail));
    if(!cards.length){
      pane.push(emptyView('+','还没有卡片',['写下问题和答案，打开时会先给你今天该复习的。'],true));
      return el('div',{'class':'pane'},...pane);
    }
    pane.push(el('div',{'class':'stat'},'待复习 '+queue.length+' · 今天已复习 '+doneToday+' · 共 '+cards.length+' 张'));
    if(!queue.length){
      const upcoming=cards.filter(c=>c.due>today).sort(fcByDue);
      const lines=[];
      if(doneToday>0)lines.push('今天已复习 '+doneToday+' 张');
      if(upcoming.length){
        const d=upcoming[0].due;
        const n=upcoming.filter(c=>c.due===d).length;
        lines.push('下次复习：'+fcDueText(d,today)+'，'+n+' 张');
      }
      const v=emptyView('✓',doneToday>0?'今天的复习完成':'今天没有要复习的卡片',lines,false);
      v.firstChild.appendChild(ruleEl());
      pane.push(v);
      return el('div',{'class':'pane'},...pane);
    }
    const c=queue[0];
    if(ui.curId!==c.id){ui.curId=c.id;ui.revealed=false;}
    const rev=!!ui.revealed;
    const flip=()=>{ui.revealed=true;redraw();};
    const fbKids=rev?[el('div',{'class':'qm'},c.q),el('div',{'class':'tx'},c.a)]:[el('div',{'class':'tx'},c.q)];
    const face=el('div',{'class':'face'+(rev?' ans':'')},
      el('div',{'class':'ft'},
        el('span',{'class':'fl'},rev?'答案':'问题'),
        el('span',{'class':'cnt'},'还剩 '+queue.length+' 张'),
        btn('ico','✎',()=>openForm(c,'review'),{'aria-label':'编辑这张卡片',title:'编辑'})),
      el('div',Object.assign({'class':'fb'},rev?{}:{onclick:flip}),...fbKids));
    let acts;
    if(!rev){
      acts=el('div',{'class':'acts'},btn('flip','翻开答案',flip));
    }else{
      const defs=[['good','记住了','✓'],['hard','勉强记得','~'],['bad','忘了','✗']];
      acts=el('div',{'class':'acts'},...defs.map(r=>{
        const p=fcPlan(c,r[0]);
        return el('button',{type:'button','class':'rate '+r[0],onclick:()=>rate(c,r[0]),'aria-label':r[1]+'，'+fcDayText(p.days)+'复习'},
          el('span',{'class':'rl'},el('b',{'class':'ic','aria-hidden':'true'},r[2]),r[1]),
          el('span',{'class':'rd'},fcDayText(p.days)));
      }));
    }
    pane.push(el('div',{'class':'rv'},face,acts));
    return el('div',{'class':'pane'},...pane);
  }


  function dots(lv){
    const ds=[];
    for(let i=1;i<=FC_MAXLV;i++)ds.push(el('i',{'class':i<=lv?'on':''}));
    return el('span',{'class':'dots',role:'img','aria-label':'熟练度 '+lv+'/'+FC_MAXLV,title:'熟练度 '+lv+'/'+FC_MAXLV},...ds);
  }
  function rowEl(c){
    const hot=c.due<=today;
    const when=c.reps?fcDueText(c.due,today):'新卡 · '+fcDueText(c.due,today);
    return el('button',{type:'button','class':'row',onclick:()=>openForm(c,'list'),'aria-label':'编辑：'+c.q},
      el('div',{'class':'rq'},c.q),
      el('div',{'class':'ra'},c.a),
      el('div',{'class':'rm'},el('span',{'class':'chip'+(hot?' hot':'')},when),dots(c.level||0)));
  }
  function listView(){
